<?php
namespace App\Http\Controllers\Api\V1\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\StoreCatalogItemRequest; use App\Http\Requests\UpdateCatalogItemRequest; use App\Http\Resources\TourResource; use App\Models\Tour; use Illuminate\Http\Request;
class TourController extends Controller { public function index(Request $request) { $q=Tour::query(); if($request->filled('search'))$q->where('name','like','%'.$request->search.'%'); return TourResource::collection($q->get()); } public function store(StoreCatalogItemRequest $request) { $data=$request->validated(); $data['image']=$this->upload($request); return (new TourResource(Tour::create($data)))->response()->setStatusCode(201); } public function show(Tour $tour) { return new TourResource($tour); } public function update(UpdateCatalogItemRequest $request,Tour $tour) { $data=$request->validated(); if($request->hasFile('image'))$data['image']=$this->upload($request); $tour->update($data); return new TourResource($tour); } public function destroy(Tour $tour) { $tour->delete(); return response()->json(status:204); } private function upload(Request $request):string { $name=$request->file('image')->getClientOriginalName(); $request->file('image')->move(public_path('images/tour-package-images'),$name); return $name; } }
